import React, { useEffect, useState } from "react";
import axios from "axios";
import "./ActivityLog.css";

const ActivityLog = () => {
  const [logs, setLogs] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [selectedMonthYear, setSelectedMonthYear] = useState(
    new Date().toLocaleString("en-US", { month: "long", year: "numeric" })
  );

  useEffect(() => {
    const fetchLogs = async () => {
      try {
        const token = localStorage.getItem("token");
        const res = await axios.get("http://127.0.0.1:8000/api/activity-logs/", {
          headers: { Authorization: `Bearer ${token}` },
        });

        const filteredLogs = res.data.filter((log) => {
          const logDate = new Date(log.timestamp);
          const [month, year] = selectedMonthYear.split(" ");
          return (
            logDate.toLocaleString("en-US", { month: "long" }) === month &&
            logDate.getFullYear().toString() === year
          );
        });

        setLogs(filteredLogs);
      } catch (err) {
        console.error(err);
        setError("Failed to load activity logs");
      } finally {
        setLoading(false);
      }
    };

    fetchLogs();
  }, [selectedMonthYear]);

  const generateMonthYearOptions = () => {
    const options = [];
    const currentDate = new Date();
    for (let i = 0; i < 12; i++) {
      const date = new Date(currentDate.getFullYear(), currentDate.getMonth() - i, 1);
      options.push(date.toLocaleString("en-US", { month: "long", year: "numeric" }));
    }
    return options;
  };

  const getActionDescription = (log) => {
    if (log.action === "update" && log.details && log.details.changes) {
      const changeStrings = Object.entries(log.details.changes).map(
        ([field, value]) => `${field} changed from "${value.from}" to "${value.to}"`
      );
      return `Updated User (${log.details.target_username}): ${changeStrings.join(", ")}`;
    }

    if (log.action === "delete")
      return `Deleted User (${log.details.target_username || "Unknown"})`;

    if (log.action === "create")
      return `Created User (${log.details.username || "Unknown"})`;

    if (log.action === "download")
      return `Downloaded ${log.details.file}`;

    return log.action || "Performed an action";
  };

  if (loading) return <p className="loading-message">Loading activity logs...</p>;
  if (error) return <p className="error-message">{error}</p>;

  return (
    <div className="activity-log-container">
      <div className="activity-log-header">
        <h2 className="header-title">Activity Log</h2>

        <div className="modern-dropdown">
          <button className="dropdown-btn">
            {selectedMonthYear} <span className="arrow">▼</span>
          </button>
          <div className="dropdown-content">
            {generateMonthYearOptions().map((option) => (
              <div
                key={option}
                className="dropdown-item"
                onClick={() => setSelectedMonthYear(option)}
              >
                {option}
              </div>
            ))}
          </div>
        </div>
      </div>

      {logs.length === 0 ? (
        <p className="no-logs-message">No activity logs found for {selectedMonthYear}.</p>
      ) : (
        <div className="activity-log-list">
          {logs.map((log, index) => (
            <div className="activity-log-item" key={index}>
              <div className="avatar">
                {log.username ? log.username.charAt(0).toUpperCase() : "U"}
              </div>

              <div className="log-user-info">
                <span className="log-user">{log.username || "Unknown User"}</span>
                <span className="log-email">{log.email || "No Email"}</span>
              </div>

              <div className="log-statement-action-group">
                <span className="log-statement-prefix">STATEMENT</span>
                <div className="log-action-text">{getActionDescription(log)}</div>
              </div>

              <div className="log-timestamp">
                {new Date(log.timestamp).toLocaleString("en-US", {
                  month: "short",
                  day: "numeric",
                  hour: "numeric",
                  minute: "numeric",
                  hour12: true,
                })}
              </div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export default ActivityLog;
